group defaultmap(source cz: BundleCZ, target eu: Bundle){
    cz.id -> eu.id;
    cz.meta -> eu.meta;
    
    cz.implicitRules as x -> eu.implicitRules=x "";
    cz.language as x -> eu.language=x "";

    cz.identifier -> eu.identifier;
    cz.type as x -> eu.type=x "";
    cz.timestamp as x -> eu.timestamp=x "";
    cz.total as x -> eu.total=x "";
    cz.link as x -> eu.link=x "";

    cz.entry as e -> eu.entry as et then{
        e.id as x-> et.id=x "";
        e.extension as x -> et.extension=x "";
        e.modifierExtension as x -> et.modifierExtension=x "";
        e.resource -> et.resource; 
        e.link as x -> et.link =x "";
        e.fullUrl as x -> et.fullUrl =x "";
        e.search as x -> et.search =x "";
        e.request as x -> et.request =x "";
        e.response as x -> et.response =x "";
    } "entry";
}

